private val activityTextFields=listOf("title","summary","assemblyLocation","paymentRuleText","safetyPolicyVersion","safetyAcknowledgementText","refundPolicyVersion","refundPolicySummary","activityDetails","contactInstructions","memberBenefitText")
private val activityListFields=listOf("safetyRequirements","includedItems","participationRequirements")
fun activityEditor(row:JSONObject?):JSONObject{val f=JSONObject().put("kind",row?.getString("kind")?:"member_night").put("coverUrl",row?.textOrNull("coverUrl")?:"").put("capacity",(row?.getInt("capacity")?:30).toString()).put("feeYuan",row?.getLong("feeAmountMinor")?.let(::activityYuan)?:"0").put("depositYuan",row?.getLong("depositAmountMinor")?.let(::activityYuan)?:"0").put("paymentMode",row?.getString("paymentMode")?:"none").put("feeBasis",row?.getString("feeBasis")?:"per_person").put("paymentDeadlineMinutes",(row?.getInt("paymentDeadlineMinutes")?:30).toString()).put("visibility",row?.getString("visibility")?:"public").put("audienceMemberLevels",row?.getJSONArray("audienceMemberLevels")?:JSONArray()).put("audienceLifecycleStages",row?.getJSONArray("audienceLifecycleStages")?:JSONArray()).put("packageSelectionRequired",row?.getBoolean("packageSelectionRequired")?:false).put("packages",JSONArray(row?.getJSONArray("packages")?.objects()?.map(::activityPackageEditor)?:emptyList<JSONObject>())).put("reason","");for(k in activityTextFields)f.put(k,row?.textOrNull(k)?:"");for(k in activityListFields)f.put(k,row?.getJSONArray(k)?.strings()?.joinToString("\n")?:"");for(k in listOf("startsAt","endsAt"))f.put(k,row?.getString(k)?.let(::calendarLocal)?:"");return f}
private fun activityYuan(n:Long)=java.math.BigDecimal(n).movePointLeft(2).toPlainString()
private fun lines(text:String)=JSONArray(text.lines().map{it.trim()}.filter{it.isNotEmpty()})
fun activityDraftFromEditor(f:JSONObject):JSONObject{val b=JSONObject().put("kind",f.getString("kind")).put("coverUrl",f.getString("coverUrl").trim().ifBlank{null}?:JSONObject.NULL).put("capacity",f.getString("capacity").toInt()).put("feeAmountMinor",giftMoney(f.getString("feeYuan"))).put("depositAmountMinor",giftMoney(f.getString("depositYuan"))).put("feeBasis",f.getString("feeBasis")).put("paymentMode",f.getString("paymentMode")).put("paymentDeadlineMinutes",f.getString("paymentDeadlineMinutes").toInt()).put("pointsReward",0).put("visibility",f.getString("visibility")).put("audienceMemberLevels",JSONArray(f.getJSONArray("audienceMemberLevels").strings().distinct().sorted())).put("audienceLifecycleStages",JSONArray(f.getJSONArray("audienceLifecycleStages").strings().distinct().sorted())).put("packageSelectionRequired",f.getBoolean("packageSelectionRequired")).put("packages",JSONArray(f.getJSONArray("packages").objects().mapIndexed{i,p->activityPackageBody(p,i)})).put("reason",f.getString("reason").trim());for(k in activityTextFields){val v=f.getString(k).trim();b.put(k,if(k=="memberBenefitText"&&v.isEmpty())JSONObject.NULL else v)};for(k in activityListFields)b.put(k,lines(f.getString(k)));for(k in listOf("startsAt","endsAt"))b.put(k,performanceTime(f.getString(k)));return b}
private val packageStrings=listOf("name","description","paymentRuleText","redemptionPolicyVersion","refundPolicyVersion")
fun activityPackageEditor(row:JSONObject?):JSONObject{val f=JSONObject().put("capacity",(row?.getInt("capacity")?:1).toString()).put("memberPurchaseLimit",(row?.getInt("memberPurchaseLimit")?:1).toString()).put("feeYuan",row?.getLong("feeAmountMinor")?.let(::activityYuan)?:"0").put("depositYuan",row?.getLong("depositAmountMinor")?.let(::activityYuan)?:"0").put("feeBasis",row?.getString("feeBasis")?:"per_person").put("paymentMode",row?.getString("paymentMode")?:"none").put("paymentDeadlineMinutes",(row?.getInt("paymentDeadlineMinutes")?:30).toString()).put("includedItems",row?.getJSONArray("includedItems")?.strings()?.joinToString("\n")?:"").put("imageUrl",row?.textOrNull("imageUrl")?:"").put("components",row?.getJSONArray("components")?:JSONArray());for(k in packageStrings)f.put(k,row?.textOrNull(k)?:"");for(k in listOf("availableFrom","availableUntil"))f.put(k,row?.textOrNull(k)?.let(::calendarLocal)?:"");return f}
private fun activityPackageBody(f:JSONObject,index:Int):JSONObject{val b=JSONObject().put("imageUrl",f.getString("imageUrl").trim().ifBlank{null}?:JSONObject.NULL).put("includedItems",lines(f.getString("includedItems"))).put("capacity",f.getString("capacity").toInt()).put("memberPurchaseLimit",f.getString("memberPurchaseLimit").toInt()).put("feeAmountMinor",giftMoney(f.getString("feeYuan"))).put("depositAmountMinor",giftMoney(f.getString("depositYuan"))).put("feeBasis",f.getString("feeBasis")).put("paymentMode",f.getString("paymentMode")).put("paymentDeadlineMinutes",f.getString("paymentDeadlineMinutes").toInt()).put("sortOrder",index).put("components",JSONArray(f.getJSONArray("components").objects().map{val qty=java.math.BigDecimal(it.getString("quantity").trim());require(qty.signum()>0&&qty.scale()<=6){"物料数量须为正数，最多六位小数"};JSONObject().put("inventoryItemId",it.getString("inventoryItemId")).put("quantity",qty.stripTrailingZeros().toPlainString()).put("perParticipant",it.getBoolean("perParticipant"))}));for(k in packageStrings){val v=f.getString(k).trim();b.put(k,if(k.endsWith("Version")&&v.isBlank())JSONObject.NULL else v)};for(k in listOf("availableFrom","availableUntil"))b.put(k,if(f.getString(k).isBlank())JSONObject.NULL else performanceTime(f.getString(k)));return b}
