@Composable private fun ActivityMultiline(label:String,value:String,max:Int,change:(String)->Unit){OutlinedTextField(value,{change(it.take(max))},label={Text(label)},minLines=2,maxLines=6,modifier=Modifier.fillMaxWidth())}
